import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import java.util.*;

public class RtlDetector extends Detector implements Detector.XmlScanner {

    public static final Issue ISSUE = Issue.create(
        "RtlSymmetry",
        "Padding and margin symmetry",
        "If you specify padding or margin on the left side of a layout, you should probably also specify padding on the right side (and vice versa) for right-to-left layout symmetry.",
        Category.RTL,
        5,
        Severity.WARNING,
        new Implementation(RtlDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        checkPair(context, element, "paddingLeft", "paddingRight");
        checkPair(context, element, "layout_marginLeft", "layout_marginRight");
    }

    private static void checkPair(XmlContext context, Element element, String leftAttr, String rightAttr) {
        boolean hasLeft = element.hasAttributeNS(ANDROID_URI, leftAttr);
        boolean hasRight = element.hasAttributeNS(ANDROID_URI, rightAttr);
        if (hasLeft && !hasRight) {
            report(context, element, leftAttr, rightAttr);
        } else if (hasRight && !hasLeft) {
            report(context, element, rightAttr, leftAttr);
        }
    }

    private static void report(XmlContext context, Element element, String specifiedAttr, String missingAttr) {
        Attr attr = element.getAttributeNodeNS(ANDROID_URI, specifiedAttr);
        if (attr == null) return;
        String message = "To support right-to-left layouts, consider adding `" + missingAttr + "` alongside `" + specifiedAttr + "`";
        context.report(ISSUE, attr, context.getLocation(attr), message);
    }
}

